<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><a href="/admin/products" class="text-link">← Productos</a><h1 class="mt-3"><?= V::escape($product['display_name'] ?? 'Nuevo producto') ?></h1><p>El identificador técnico permanece estable aunque cambie el nombre comercial.</p></div></div>
<div class="row g-4"><div class="col-xl-7"><form class="panel form-panel" method="post" action="/admin/products/<?= V::escape($product['product_id'] ?? 'create') ?>"><?php V::fields($csrf); ?><input type="hidden" name="version" value="<?= (int) ($product['row_version']??0) ?>"><fieldset <?= $actor->role!=='superadmin'?'disabled':'' ?>><div class="stack-form"><div><label class="form-label" for="product_id">Identificador técnico</label><input class="form-control" id="product_id" name="product_id" value="<?= V::escape($product['product_id'] ?? '') ?>" pattern="[a-z][a-z0-9_]{1,63}" maxlength="64" <?= $product?'readonly':'' ?> required></div><div><label class="form-label" for="name">Nombre comercial</label><input class="form-control" id="name" name="name" value="<?= V::escape($product['display_name'] ?? '') ?>" maxlength="190" required></div><div><label class="form-label" for="description">Descripción</label><textarea class="form-control" id="description" name="description" maxlength="500" rows="3"><?= V::escape($product['description'] ?? '') ?></textarea></div><div><label class="form-label" for="state">Estado</label><select class="form-select" id="state" name="state"><option value="active">Activo</option><option value="archived" <?= ($product['state']??'')==='archived'?'selected':'' ?>>Archivado</option></select><div class="form-text">Archivar impide nuevas emisiones y conserva las licencias existentes.</div></div></div><?php if ($actor->role==='superadmin'): ?><div class="form-footer"><button class="btn btn-primary">Guardar producto</button></div><?php endif; ?></fieldset></form></div>
<div class="col-xl-5"><section class="panel form-panel"><h2>Capacidades</h2><?php if (!$product): ?><p class="text-secondary">Guarda el producto para definir sus capacidades y dependencias.</p><?php endif; ?><?php foreach ($capabilities as $capability): ?><div class="capability-row"><strong><?= V::escape($capability['display_name']) ?></strong><code><?= V::escape($capability['capability_key']) ?></code><?php if ($capability['requires_keys']): ?><small>Requiere: <?= V::escape($capability['requires_keys']) ?></small><?php endif; ?></div><?php endforeach; ?><?php if (($product['product_id']??'')==='gestor_documental'): ?><div class="note-box mt-3">El modo híbrido combina bibliotecas vinculadas y administradas. Las cargas en expedientes requieren bibliotecas administradas.</div><?php endif; ?></section>
<?php if ($product && $actor->role==='superadmin'): ?><form class="panel form-panel mt-4" method="post" action="/admin/products/<?= V::escape($product['product_id']) ?>/capabilities"><?php V::fields($csrf); ?><h2>Definir capacidad</h2><p class="text-secondary small">Usa una clave existente para editarla. Las dependencias deben ser compatibles con las licencias emitidas.</p><div class="stack-form"><div><label class="form-label" for="capability_key">Clave de capacidad</label><input class="form-control" id="capability_key" name="capability_key" pattern="[a-z][a-z0-9_]{1,63}" maxlength="64" required></div><div><label class="form-label" for="cap_name">Nombre visible</label><input class="form-control" id="cap_name" name="name" maxlength="190" required></div><div><label class="form-label" for="requires">Capacidades requeridas</label><input class="form-control" id="requires" name="requires" maxlength="1000" placeholder="clave_uno,clave_dos"></div><button class="btn btn-outline-primary">Guardar capacidad</button></div></form><?php endif; ?></div></div>
